/* steel-toggle v1.0.1 — vendor build (PNG-only render path) for vasu-yadav-portfolio.
 * Self-contained ES module (no imports). No canvas/WebGL: state art is pure PNG.
 * Art override: --steel-toggle-light / --steel-toggle-dark (defaults: ./toggle-*.png
 * next to this file). Controlled mode: the page owns theme state; this element
 * reflects `checked` / aria-checked and fires `change` with target.checked.
 * Sound adapted from github.com/kvvasu/steel-toggle (MIT). */

const SOUND_PROFILES = {
  weighted: { duration: 0.075, body: 550, decay: 90, weight: 0.12, snap: 0.62, rebound: 0.012 },
  crisp: { duration: 0.065, body: 650, decay: 100, weight: 0.08, snap: 0.62, rebound: 0.007 },
  heavy: { duration: 0.13, body: 185, decay: 42, weight: 0.34, snap: 0.52, rebound: 0.014 },
  damped: { duration: 0.085, body: 135, decay: 68, weight: 0.26, snap: 0.25, rebound: 0.009 },
  chunky: { duration: 0.16, body: 110, decay: 34, weight: 0.43, snap: 0.43, rebound: 0.021 },
  metallic: { duration: 0.19, body: 920, decay: 30, weight: 0.2, snap: 0.56, rebound: 0.011 },
  relay: { duration: 0.09, body: 390, decay: 76, weight: 0.18, snap: 0.7, rebound: 0.025 },
  latch: { duration: 0.14, body: 235, decay: 48, weight: 0.32, snap: 0.4, rebound: 0.032 },
};

const LIGHT_ART = new URL("./toggle-light.png", import.meta.url).href;
const DARK_ART = new URL("./toggle-dark.png", import.meta.url).href;

let audioCtx;

function playToggleSound(name = "weighted", toDark = false) {
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return;
  try {
    audioCtx ??= new AC();
    if (audioCtx.state === "suspended") audioCtx.resume();
    const p = SOUND_PROFILES[name] || SOUND_PROFILES.weighted;
    const sr = audioCtx.sampleRate;
    const buf = audioCtx.createBuffer(1, Math.ceil(sr * p.duration), sr);
    const d = buf.getChannelData(0);
    let seed = 1947;
    const rnd = () => ((seed = (seed * 1664525 + 1013904223) >>> 0), seed / 2147483648 - 1);
    const pitch = toDark ? 0.96 : 1.04;
    for (let i = 0; i < d.length; i++) {
      const u = i / sr, f = rnd();
      const snap = p.snap * f * Math.exp(-u * 510);
      const rebound = u < p.rebound ? 0 : f * 0.24 * Math.exp(-(u - p.rebound) * 330);
      const body = p.weight * Math.exp(-u * p.decay) *
        (Math.sin(2 * Math.PI * p.body * pitch * u) * 0.62 +
         Math.sin(2 * Math.PI * p.body * 2.73 * u) * 0.24 +
         Math.sin(2 * Math.PI * p.body * 6.31 * u) * 0.14);
      const rumble = f * 0.1 * Math.exp(-u * 95);
      d[i] = Math.tanh((snap + rebound + body + rumble) * 1.3) * 0.65 *
             Math.min(u / 4e-4, 1) * Math.min((p.duration - u) / 0.005, 1);
    }
    const src = audioCtx.createBufferSource();
    src.buffer = buf;
    src.connect(audioCtx.destination);
    src.start();
  } catch { /* audio is best-effort */ }
}

class SteelToggle extends HTMLElement {
  static observedAttributes = ["checked", "muted"];

  #button = null;

  connectedCallback() {
    if (this.shadowRoot) return;
    const root = this.attachShadow({ mode: "open" });
    root.innerHTML = `
      <style>
        :host { display: inline-flex; min-width: 44px; min-height: 44px; align-items: center; justify-content: center; --focus: currentColor; }
        button {
          appearance: none; display: block; width: 84px; height: 44px; padding: 0; border: 0;
          border-radius: 5px; background: transparent; cursor: pointer; position: relative;
          touch-action: manipulation; -webkit-tap-highlight-color: transparent;
        }
        button::before { content: ""; position: absolute; inset: -2px 0; }
        button:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }
        .fallback {
          position: absolute; inset: 0;
          background: var(--steel-toggle-light, url("${LIGHT_ART}")) center / 100% 100% no-repeat;
        }
        button[aria-checked="true"] .fallback {
          background-image: var(--steel-toggle-dark, url("${DARK_ART}"));
        }
      </style>
      <button type="button" role="switch" aria-label="Toggle dark mode" aria-checked="false" title="Toggle dark mode">
        <span class="fallback" aria-hidden="true"></span>
      </button>`;
    this.#button = root.querySelector("button");
    this.#sync();

    const flip = () => {
      this.checked = !this.checked;
      this.dispatchEvent(new Event("change", { bubbles: true }));
      if (!this.hasAttribute("muted") && document.documentElement.getAttribute("data-sound") !== "muted") {
        playToggleSound(this.getAttribute("sound") || "weighted", this.checked);
      }
    };
    this.#button.addEventListener("click", flip);
    this.#button.addEventListener("keydown", (e) => {
      if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
        e.preventDefault();
        const wantChecked = e.key === "ArrowRight";
        if (wantChecked !== this.checked) flip();
      }
    });
  }

  attributeChangedCallback() {
    this.#sync();
  }

  get checked() {
    return this.hasAttribute("checked");
  }

  set checked(v) {
    this.toggleAttribute("checked", Boolean(v));
  }

  #sync() {
    const on = this.checked;
    this.toggleAttribute("data-dark", on);
    if (this.#button) {
      this.#button.setAttribute("aria-checked", String(on));
      this.#button.title = on ? "Switch to light mode" : "Switch to dark mode";
    }
  }
}

if (typeof customElements !== "undefined" && !customElements.get("steel-toggle")) {
  customElements.define("steel-toggle", SteelToggle);
}
